package admin

const stylesheet = `
:root{color-scheme:light;--paper:#f7f5ed;--ink:#203a30;--muted:#506558;--green:#245b43;--line:#c8d0bf;--wash:#ecf0e5;--warning:#8c3d20;--focus:#b84f21}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 90% 0,#e6eddc 0,transparent 55%),var(--paper);color:var(--ink);font:1rem/1.6 "Avenir Next","Segoe UI",sans-serif;min-height:100vh}main{max-width:1120px;margin:auto;padding:2.5rem 2rem 3rem}.narrow{max-width:520px;padding-top:9vh}.editor{max-width:780px}header,.page-title,.account-heading,.actions{display:flex;align-items:center;justify-content:space-between;gap:1rem;flex-wrap:wrap}.brand{font-weight:650;text-decoration:none;letter-spacing:-.02em}.brand span{font-family:Georgia,serif;font-style:italic;font-weight:400;padding:0 .25em}h1,h2,legend{font-family:Georgia,"Palatino Linotype",serif;font-weight:400;line-height:1.15}h1{font-size:clamp(2.35rem,5vw,3.8rem);letter-spacing:-.03em;margin:2rem 0 1rem}h2{font-size:1.8rem;margin:0}p{max-width:70ch;margin:.6rem 0 1.2rem}a{color:var(--green);text-underline-offset:.22em;overflow-wrap:anywhere}a:hover{text-decoration-thickness:2px}button,.button{font:inherit;line-height:1.35;display:inline-block;border:1px solid var(--green);border-radius:5px;padding:.65rem 1rem;min-height:44px;background:var(--green);color:#fff;text-decoration:none;cursor:pointer}button:hover,.button:hover{background:#17432f;color:#fff}button.quiet{background:transparent;color:var(--green)}button.quiet:hover{background:var(--wash)}button.danger{background:transparent;border-color:var(--warning);color:var(--warning)}button:disabled{opacity:.55;cursor:not-allowed}input,textarea,button{accent-color:var(--green)}:focus-visible{outline:3px solid var(--focus);outline-offset:3px}::selection{background:#c9dcb5;color:#102d21}input,textarea{font:1rem/1.5 "Avenir Next","Segoe UI",sans-serif;caret-color:var(--green)}input:not([type=checkbox]),textarea{width:100%;padding:.65rem .75rem;background:#fffdf7;border:1px solid #7d8e7a;border-radius:4px;color:var(--ink);margin-top:.4rem}input::placeholder{color:#60705e}input[readonly]{background:var(--wash)}textarea{resize:vertical;min-height:7rem}label{display:block;font-size:.9rem;font-weight:600;overflow-wrap:anywhere}.stack{display:grid;gap:1.15rem;max-width:100%}fieldset{border:1px solid var(--line);border-radius:6px;margin:1rem 0 0;padding:1.5rem;min-width:0}legend{font-size:1.5rem;padding:0 .5rem}.check{display:flex;align-items:flex-start;gap:.6rem;font-weight:450}.check input{width:1.15rem;height:1.15rem;flex-shrink:0;margin:.2rem 0}.check small{display:block;color:var(--muted)}.note,.scope,footer{font-size:.86rem;color:var(--muted)}.stack>.note{margin:-.8rem 0 0}.page-title{margin-bottom:2rem}.account{padding:2rem 0;border-top:1px solid var(--line)}.scope{margin:.7rem 0 1.5rem}.scope span{padding:0 .5rem}.state,code,dt{font-family:"SFMono-Regular",Consolas,"Liberation Mono",monospace;font-size:.8rem}.state{border:1px solid var(--line);border-radius:4px;padding:.25rem .6rem;overflow-wrap:anywhere;max-width:100%}.queue{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:1rem;margin:1rem 0 1.5rem}.queue dt{color:var(--muted);font-size:.72rem}.queue dd{margin:.25rem 0 0;font-size:1.5rem;font-variant-numeric:tabular-nums;line-height:1.2}.actions{justify-content:flex-start;margin:1.25rem 0}.actions a{padding:.5rem}details{margin:1rem 0}summary{cursor:pointer;text-underline-offset:.25em;text-decoration:underline}details>p{margin-top:.75rem}.diagnostics{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:.5rem 1rem;max-width:700px}.diagnostics dt,.diagnostics dd{padding:.6rem 0;border-bottom:1px solid var(--line);overflow-wrap:anywhere}.diagnostics dd{margin:0}.notice{padding:1rem 1.25rem;background:var(--wash);border-radius:4px}.empty{margin:3rem 0;padding:2rem 0;border-top:1px solid var(--line)}.empty h2{margin-bottom:1rem}footer{border-top:1px solid var(--line);padding-top:1.5rem;margin-top:2rem}.album-list{max-height:22rem;overflow:auto;scrollbar-color:var(--line) var(--paper);padding:.25rem}.album-list label{padding:.5rem 0}nav{margin-top:2rem}main{animation:arrive .4s cubic-bezier(.16,1,.3,1)}@keyframes arrive{from{transform:translateY(6px)}to{transform:translateY(0)}}
@media(max-width:760px){.queue{grid-template-columns:repeat(4,minmax(0,1fr));row-gap:1.4rem}main{padding:1.5rem 1.1rem 2rem}.page-title{align-items:flex-start}.account-heading{align-items:flex-start}.brand{font-size:.9rem}.editor fieldset{padding:1rem}.narrow{padding-top:8vh}.diagnostics{grid-template-columns:minmax(0,1fr)}.diagnostics dt{border:0;padding-bottom:0}.diagnostics dd{padding-top:0}.actions{gap:.65rem}}
@media(max-width:380px){.queue{grid-template-columns:repeat(2,minmax(0,1fr))}.actions button{width:100%}}
@media(prefers-reduced-motion:reduce){main{animation:none}}
`
